SELECT *, AVG(shipping_fee) OVER (ORDER BY discount, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS shipping_fee_avg_3, FIRST_VALUE(shipping_fee, TRUE) OVER (PARTITION BY status ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_shipping_fee, LEAD(shipping_fee, 2, 0) OVER (ORDER BY amount, id) AS next_shipping_fee, NTILE(5) OVER (ORDER BY discount, id) AS discount_bucket FROM orders
